var a = new Date();
var d = new Date(a.getFullYear(), a.getMonth(), a.getDate() - 6);
var e = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1);
var iniciolectura = String(d.getTime());
var finlectura = String(e.getTime());

var linea;
try {
  var res = JSON.parse(healthconnectresult);
  var t = res.records.filter(function (x) {
    return x.metadata.dataOrigin.packageName === "com.rafapps.taskerhealthconnect";
  });
  linea = new Date(Number(iniciolectura)).toDateString() +
    " | total=" + res.records.length +
    " | page=" + (res.pageToken ? "MORE" : "end") +
    " | tasker=" + t.length + "\n";
  t.forEach(function (x) { linea += "  " + JSON.stringify(x) + "\n"; });
} catch (err) {
  linea = "dia -3: ERROR " + err + "\n";
}
writeFile("/sdcard/Download/pasos_inventario.txt", linea, true);

