var a = new Date();
var d = new Date(a.getFullYear(), a.getMonth(), a.getDate() - 3);
var e = new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1);
var iniciolectura = String(d.getTime());
var finlectura = String(e.getTime());

var ahora = new Date();

function clave(d) {
  return d.getFullYear() + "-" +
    ("0" + (d.getMonth() + 1)).slice(-2) + "-" +
    ("0" + d.getDate()).slice(-2);
}

// Los días hasta el 25-10 tienen registros sin clientRecordId; reescribirlos los duplicaría.
var desde = "2026-10-25";

var pendientes = [];

for (var i = 6; i >= 0; i--) {
  var dia = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate() - i);
  var k = clave(dia);
  if (k <= desde) continue;

  var fin = new Date(dia.getFullYear(), dia.getMonth(), dia.getDate(), 23, 50);
  // No registrar hoy antes de las 23:50.
  if (fin.getTime() > ahora.getTime()) continue;

  // Se reescriben todos los días cada vez: clientRecordId hace que
  // Health Connect actualice en vez de duplicar, y repone días borrados.
  pendientes.push({
    startTime: dia.getTime(),
    endTime: fin.getTime(),
    count: 25000,
    metadata: { clientRecordId: "pasos-" + k, clientRecordVersion: 1 }
  });
}

var pasosjson = JSON.stringify(pendientes);
var haypendientes = pendientes.length ? "1" : "0";
